"use client"
import { useEffect, useState } from "react"
import { potwFetch } from "./session"
import type { ImageAccess } from "@/lib/potw/types"

// URLs are cached per mounted gallery, not regenerated by each image render.
export function usePrivateImages(ids: string[], admin = false, variant: "thumbnail" | "display" = "thumbnail", active = true) {
  const [images, setImages] = useState<Record<string, ImageAccess>>({}), [error, setError] = useState("")
  const [unavailable, setUnavailable] = useState<string[]>([])
  const key = ids.filter(Boolean).join(",")
  useEffect(() => {
    let alive = true, timer: ReturnType<typeof setTimeout> | undefined
    setImages({}); setUnavailable([]); setError("")
    if (!active || !key) return
    async function refresh() {
      if (!alive) return
      if (document.visibilityState === "hidden") { timer = setTimeout(refresh, 30000); return }
      try {
        const data = await potwFetch<{ images: Record<string, ImageAccess>; unavailable: string[] }>("/api/potw/image-access", { method: "POST", body: JSON.stringify({ ids: key.split(","), admin, variant }) })
        if (alive) { setImages(data.images); setUnavailable(data.unavailable); setError(""); timer = setTimeout(refresh, 240000) }
      } catch (e) { if (alive) setError(e instanceof Error ? e.message : "Images unavailable") }
    }
    void refresh()
    return () => { alive = false; clearTimeout(timer) }
  }, [key, admin, variant, active])
  return { images, unavailable, error }
}
